UPDATE `cards` SET `description` = '抽 1 张牌，并为自己增加 1 点防御', `card_type` = 'draw', `cost` = 1 WHERE `card_code` = 'H-01';
DELETE e FROM `card_effects` e INNER JOIN `cards` c ON c.id = e.card_id WHERE c.card_code = 'H-01';

