DELETE e FROM `card_effects` e INNER JOIN `cards` c ON c.id = e.card_id WHERE c.card_code = 'H-02';

UPDATE `cards` SET `description` = '本回合员工调用机会 +1，并抽 1 张牌', `card_type` = 'support', `cost` = 2 WHERE `card_code` = 'H-03';
